using DriveOS.Application.Abstractions.Messaging; using DriveOS.Application.Abstractions.Time; using DriveOS.Modules.Workforce.Application.Persistence; using DriveOS.Modules.Workforce.Domain.Employees; using DriveOS.Modules.Workforce.Domain.WorkingTime; using DriveOS.SharedKernel.Identifiers; using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.Workforce.Application.WorkingTime;
public sealed class CreateWorkingTimePolicyCommandHandler(IWorkingTimePolicyRepository repo,IEmployeeRepository employees,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<CreateWorkingTimePolicyCommand,WorkingTimePolicyId>{public async Task<Result<WorkingTimePolicyId>> Handle(CreateWorkingTimePolicyCommand c,CancellationToken ct){if(await employees.GetByIdAsync(c.OrganizationId,c.EmployeeId,ct)is null)return Result.Failure<WorkingTimePolicyId>(EmployeeErrors.NotFound);if(await repo.HasOverlapAsync(c.OrganizationId,c.EmployeeId,c.EffectiveFrom,c.EffectiveTo,null,ct))return Result.Failure<WorkingTimePolicyId>(WorkingTimeErrors.OverlappingPolicy);var r=WorkingTimePolicy.Create(c.PolicyId,c.OrganizationId,c.EmployeeId,c.EffectiveFrom,c.EffectiveTo,c.ContractualWeeklyHours,c.ContractualDailyHours,c.MaxWorkingDaysPerWeek);if(r.IsFailure)return Result.Failure<WorkingTimePolicyId>(r.Error);r.Value.SetCreatedAudit(clock.UtcNow,c.ActorUserId);repo.Add(r.Value);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
public sealed class UpdateWorkingTimePolicyCommandHandler(IWorkingTimePolicyRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<UpdateWorkingTimePolicyCommand>{public async Task<Result> Handle(UpdateWorkingTimePolicyCommand c,CancellationToken ct){var p=await repo.GetAsync(c.OrganizationId,c.PolicyId,true,ct);if(p is null)return Result.Failure(WorkingTimeErrors.NotFound);if(await repo.HasOverlapAsync(c.OrganizationId,p.EmployeeId,c.EffectiveFrom,c.EffectiveTo,c.PolicyId,ct))return Result.Failure(WorkingTimeErrors.OverlappingPolicy);var r=p.Update(c.EffectiveFrom,c.EffectiveTo,c.ContractualWeeklyHours,c.ContractualDailyHours,c.MaxWorkingDaysPerWeek,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class DeactivateWorkingTimePolicyCommandHandler(IWorkingTimePolicyRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<DeactivateWorkingTimePolicyCommand>{public async Task<Result> Handle(DeactivateWorkingTimePolicyCommand c,CancellationToken ct){var p=await repo.GetAsync(c.OrganizationId,c.PolicyId,true,ct);if(p is null)return Result.Failure(WorkingTimeErrors.NotFound);var r=p.Deactivate(clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class GetWorkingTimePoliciesQueryHandler(IWorkingTimePolicyRepository repo):IQueryHandler<GetWorkingTimePoliciesQuery,IReadOnlyList<WorkingTimePolicyResponse>>{public async Task<Result<IReadOnlyList<WorkingTimePolicyResponse>>> Handle(GetWorkingTimePoliciesQuery q,CancellationToken ct)=>Result.Success<IReadOnlyList<WorkingTimePolicyResponse>>((await repo.ListAsync(q.OrganizationId,q.EmployeeId,ct)).Select(x=>new WorkingTimePolicyResponse(x.Id.Value,x.EmployeeId.Value,x.EffectiveFrom,x.EffectiveTo,x.ContractualWeeklyHours,x.ContractualDailyHours,x.MaxWorkingDaysPerWeek,x.Status.ToString())).ToArray());}
public sealed class GetWorkingTimeSummaryQueryHandler(IWorkingTimePolicyRepository repo,IWorkingTimeProjectionGateway gateway):IQueryHandler<GetWorkingTimeSummaryQuery,WorkingTimeSummaryResponse>{public async Task<Result<WorkingTimeSummaryResponse>> Handle(GetWorkingTimeSummaryQuery q,CancellationToken ct){if(q.To<q.From)return Result.Failure<WorkingTimeSummaryResponse>(WorkingTimeErrors.InvalidPeriod);var policies=await repo.ListAsync(q.OrganizationId,q.EmployeeId,ct);decimal contractual=0;for(var d=q.From;d<=q.To;d=d.AddDays(1)){var p=policies.Where(x=>x.Status==WorkingTimePolicyStatus.Active&&x.EffectiveFrom<=d&&(!x.EffectiveTo.HasValue||x.EffectiveTo.Value>=d)).OrderByDescending(x=>x.EffectiveFrom).FirstOrDefault();if(p is null)continue;contractual+=p.ContractualWeeklyHours/7m;}var projection=await gateway.GetAsync(q.OrganizationId,q.EmployeeId,q.From,q.To,ct);return Result.Success(new WorkingTimeSummaryResponse(q.EmployeeId.Value,q.From,q.To,decimal.Round(contractual,2),projection.PlannedHours,projection.ActualTeachingHours,projection.ApprovedLeaveHours,decimal.Round(projection.PlannedHours+projection.ApprovedLeaveHours-contractual,2)));}}
